    return G
import re
G=load()
def transform(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    # separator rows: rows not equal to bg where... find rows/cols fully of a single non-bg color
    H,W=len(g),len(g[0])
    sep_rows=[i for i in range(H) if len(set(g[i]))==1 and g[i][0]!=bg]
    sep_cols=[j for j in range(W) if len(set(g[i][j] for i in range(H)))==1 and g[i][j]!=bg]
    # pattern: contiguous tile region (rows not sep, cols not sep) containing non-bg non-sep colors
    def blocks(idxs,n):
        out=[];s=None
        for i in range(n+1):
            if i<n and i not in idxs:
                if s is None: s=i
            else:
                if s is not None: out.append((s,i)); s=None
        return out
    rb=blocks(set(sep_rows),H); cb=blocks(set(sep_cols),W)
    pat=None
    for r0,r1 in rb:
        for c0,c1 in cb:
            tile=[row[c0:c1] for row in g[r0:r1]]
            if any(x!=bg for row in tile for x in row):
                pat=tile
    out=[row[:] for row in g]
    for r0,r1 in rb:
        for c0,c1 in cb:
            tile=[row[c0:c1] for row in g[r0:r1]]
            if all(x==bg for row in tile for x in row) and pat:
                for i in range(r1-r0):
                    for j in range(c1-c0):
                        out[r0+i][c0+j]=pat[i][j]
    return out
